CREATE VIEW [CE].[vwContact_Age_Groups] AS

WITH CTE AS (
	SELECT 
	DATEDIFF(YY,BirthDate, GETDATE()) As Age
	FROM [CE].[vwContact]
	WHERE BirthDate IS NOT NULL
	GROUP BY DATEDIFF(YY,BirthDate, GETDATE())
	)

SELECT
 Age
,CASE
	--WHEN Age IS NULL THEN 'Not Known'
	WHEN Age < 0 THEN '< 0'
	WHEN Age < 18 THEN '< 18' 
	WHEN AGE BETWEEN 18 AND 25 THEN '18-25'
	WHEN AGE BETWEEN 26 AND 30 THEN '26-30'
	WHEN AGE BETWEEN 31 AND 40 THEN '31-40'
	WHEN AGE BETWEEN 41 AND 50 THEN '41-50'
	WHEN AGE BETWEEN 51 AND 60 THEN '51-60'
	WHEN AGE BETWEEN 61 AND 70 THEN '61-70'
	WHEN AGE BETWEEN 71 AND 80 THEN '71-80'
	WHEN AGE > 80 THEN '80+'
	END AS 'Age Group'
,CASE
	--WHEN Age IS NULL THEN 0
	WHEN Age < 0 THEN 1
	WHEN Age < 18 THEN 2
	WHEN AGE BETWEEN 18 AND 25 THEN 3
	WHEN AGE BETWEEN 26 AND 30 THEN 4
	WHEN AGE BETWEEN 31 AND 40 THEN 5
	WHEN AGE BETWEEN 41 AND 50 THEN 6
	WHEN AGE BETWEEN 51 AND 60 THEN 7
	WHEN AGE BETWEEN 61 AND 70 THEN 8
	WHEN AGE BETWEEN 71 AND 80 THEN 9
	WHEN AGE > 80 THEN 10
	END AS 'Age Group Sort'
,CASE
	WHEN AGE IS NULL THEN 'N/A'
	WHEN AGE BETWEEN 21 AND 34 THEN '21-34'
	ELSE 'Other Age' END AS 'Age Group Alt'
FROM CTE
